SELECT det.id AS id, det.create_time AS createTime, det.update_time AS updateTime, det.create_user_name AS createUserName, det.create_user_id AS createUserId, det.update_user_name AS updateUserName, det.update_user_id AS updateUserId, det.version AS version, det.is_deleted AS isDeleted, det.cfg_etl_id AS cfgEtlId, det.start_time AS startTime, det.end_time AS endTime, det.status AS status, det.error_message AS errorMessage, det.error_count AS errorCount, det.exec_timeout AS execTimeout, det.extend_json AS extendJson, det.next_exec_time AS nextExecTime, det.instance_id AS instanceId, 'restCloud' AS execSystem, dce.exec_url AS execUrl, dce.flow_name AS flowName from dmp_etl_task det left join dmp_cfg_etl dce on det.cfg_etl_id = dce.id where ${params.sqlMap.default} and det.is_deleted = false
${params.permissionSql}
order by det.update_time desc

SELECT CASE WHEN status IN ('init', 'fds', 'mongo', 'dmp') THEN 'waitFinish' WHEN status = 'error' THEN 'error' WHEN status = 'finish' THEN 'finish' ELSE status END AS tabFlag, CASE WHEN status IN ('init', 'fds', 'mongo', 'dmp') THEN '待完成' WHEN status = 'error' THEN '异常' WHEN status = 'finish' THEN '完成' ELSE status END AS tabFlagName, COUNT(*) AS count FROM dmp_etl_task WHERE is_deleted = FALSE
${params.permissionSql}
GROUP BY tabFlag, tabFlagName
